"use client"

/** Selectable findings. The selected row is a raised card. */

import * as React from "react"
import { Check, TriangleAlert, X } from "lucide-react"

import { cn } from "@/lib/utils"
import { CollectionPhaseNotice, type CollectionPhase } from "@/lib/collection-phase"

export type IssueSeverity = "pass" | "minor" | "critical" | "fixed"

export type IssueListItem = {
  id: string
  title: string
  description?: string
  severity: IssueSeverity
  badge?: React.ReactNode
}

export type IssueListProps = {
  label?: string
  items: readonly IssueListItem[]
  value?: string
  onValueChange?: (id: string) => void
  emptyLabel?: string
  className?: string
  phase?: CollectionPhase
  disabled?: boolean
  phaseLabel?: string
}

const iconWrap: Record<IssueSeverity, string> = {
  pass: "bg-primary/15 text-foreground",
  minor: "bg-chart-4/20 text-foreground",
  critical: "bg-destructive/10 text-destructive",
  fixed: "bg-primary/15 text-foreground",
}

function Mark({ severity }: { severity: IssueSeverity }) {
  const Icon = severity === "critical" ? X : severity === "minor" ? TriangleAlert : Check
  return (
    <span aria-hidden className={cn("grid size-7 shrink-0 place-items-center rounded-full", iconWrap[severity])}>
      <Icon className="size-3.5" />
    </span>
  )
}

export function IssueList({ label = "Findings", items, value, onValueChange, emptyLabel = "None", className, phase = "ready", disabled = false, phaseLabel }: IssueListProps) {
  if (phase === "loading" || phase === "error") {
    return (
      <section data-slot="issue-list" data-phase={phase} inert={disabled || undefined} className={cn("rounded-xl border border-border bg-card p-3", className)}>
        <CollectionPhaseNotice phase={phase} label={phaseLabel} />
      </section>
    )
  }
  const shown = phase === "empty" ? [] : items
  function onKey(event: React.KeyboardEvent<HTMLButtonElement>, index: number) {
    if (event.key !== "ArrowDown" && event.key !== "ArrowUp") return
    event.preventDefault()
    const next = event.key === "ArrowDown" ? Math.min(shown.length - 1, index + 1) : Math.max(0, index - 1)
    onValueChange?.(shown[next]?.id ?? "")
    const rows = event.currentTarget.closest("ul")?.querySelectorAll<HTMLButtonElement>("[data-issue]")
    rows?.[next]?.focus()
  }
  return (
    <section data-slot="issue-list" data-phase={phase} inert={disabled || undefined} className={cn("flex min-w-0 flex-col gap-2", disabled && "opacity-60", className)}>
      <div className="flex items-center justify-between gap-2">
        <h3 className="text-sm font-medium">{label}</h3>
        <span className="font-mono text-xs text-muted-foreground">{shown.length}</span>
      </div>
      {shown.length === 0 ? (
        <p className="text-sm text-muted-foreground">{phaseLabel ?? emptyLabel}</p>
      ) : (
        <ul role="listbox" aria-label={label} className="flex flex-col gap-1">
          {shown.map((item, index) => {
            const selected = item.id === value
            return (
              <li key={item.id}>
                <button
                  type="button"
                  role="option"
                  data-issue=""
                  aria-selected={selected}
                  onClick={() => onValueChange?.(item.id)}
                  onKeyDown={(event) => onKey(event, index)}
                  className={cn(
                    "flex w-full items-start gap-2 rounded-xl px-2 py-2 text-start focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
                    selected ? "border border-border bg-card shadow-sm" : "hover:bg-muted",
                  )}
                >
                  <Mark severity={item.severity} />
                  <span className="min-w-0 flex-1">
                    <span className="block text-sm font-medium wrap-break-word">{item.title}</span>
                    {item.description ? <span className="mt-0.5 line-clamp-2 block text-xs text-muted-foreground">{item.description}</span> : null}
                  </span>
                  {item.badge}
                </button>
              </li>
            )
          })}
        </ul>
      )}
    </section>
  )
}

"use client"

import { cn } from "@/lib/utils"

/** How a piece that lists records is getting its data. */
export type CollectionPhase = "ready" | "loading" | "empty" | "error"

const fallback = {
  loading: "Loading",
  empty: "Nothing here yet",
  error: "Something went wrong",
} as const

export function CollectionPhaseNotice({
  phase,
  label,
  className,
}: {
  phase: Exclude<CollectionPhase, "ready">
  label?: string
  className?: string
}) {
  const error = phase === "error"
  return (
    <p
      role={error ? "alert" : "status"}
      aria-busy={phase === "loading" || undefined}
      data-phase={phase}
      className={cn("text-sm text-pretty", error ? "text-destructive" : "text-muted-foreground", className)}
    >
      {label ?? fallback[phase]}
    </p>
  )
}
